import * as T from './vendor/three.module.js';
import {buildTrain,buildWalkingForest,buildBeach} from './journey-worlds.js';
import {chapters,clamp,sandHeight,shoreX} from './journey-math.js';
import {NatureAudio} from './journey-audio.js';
import {trailX,walkHeight,stepWalker} from './forest-math.js';
const $=id=>document.getElementById(id),canvas=$('journeyCanvas');let renderer;
try{renderer=new T.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true})}catch{$('error').hidden=false;throw new Error('WebGL unavailable')}
renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene(),camera=new T.PerspectiveCamera(64,1,.08,280),audio=new NatureAudio(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
scene.fog=new T.FogExp2('#b9c9bb',.015);const sun=new T.DirectionalLight('#fff0cc',2.5);sun.position.set(28,38,-20);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=sun.shadow.camera.bottom=-53;sun.shadow.camera.right=sun.shadow.camera.top=53;sun.shadow.camera.far=150;sun.shadow.normalBias=.035;scene.add(sun);
const ambient=new T.HemisphereLight('#e4ebd6','#6e826b',2.2);scene.add(ambient);
const skyU={top:{value:new T.Color('#91b8bc')},bottom:{value:new T.Color('#dce0c6')},direction:{value:new T.Vector3(.7,.32,.4).normalize()}};
const sky=new T.Mesh(new T.SphereGeometry(250,32,16),new T.ShaderMaterial({uniforms:skyU,side:T.BackSide,depthWrite:false,vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 p;uniform vec3 top;uniform vec3 bottom;uniform vec3 direction;void main(){vec3 d=normalize(p);vec3 c=mix(bottom,top,pow(max(0.,d.y),.7));float a=max(dot(d,direction),0.);c+=vec3(1.,.85,.55)*(pow(a,400.)*.5+pow(a,2000.));gl_FragColor=vec4(c,1.);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'}));scene.add(sky);
const worlds={train:buildTrain(),forest:buildWalkingForest(),beach:buildBeach()};Object.values(worlds).forEach(w=>scene.add(w.root));
const state={chapter:'train',started:false,time:0,sceneTime:0,route:0,line:0,lineTime:0,hold:false,auto:false,clean:false,back:false,x:0,z:0,yaw:-Math.PI/2+.1,pitch:-.08},keys=new Set();let last=performance.now(),transition=null,viewMove=null,drag=null,uiClock=0;
const palettes={train:{fog:'#cbd5bf',density:.009,top:'#9ebdc1',bottom:'#e3e2c8',sun:'#fff1d5',pos:[28,38,-20],ground:'#71816b',intensity:2.4},forest:{fog:'#b6c6ac',density:.017,top:'#93b5b4',bottom:'#d6dbc0',sun:'#fff0c4',pos:[-20,40,-20],ground:'#6d846a',intensity:2.7},beach:{fog:'#c5d8d0',density:.006,top:'#9fbfc5',bottom:'#eddbc1',sun:'#ffe0b4',pos:[-30,22,35],ground:'#a6ac91',intensity:2.3}};
function updateSound(){$('sound').querySelector('span').textContent=audio.enabled?'자연음 켬':'소리 켜기';$('sound').setAttribute('aria-pressed',String(audio.enabled));$('sound').setAttribute('aria-label',audio.enabled?'자연음 끄기':'자연음 켜기');canvas.dataset.audio=audio.enabled?'on':'off';}
function paintStory(){const i=chapters.findIndex(c=>c.id===state.chapter),c=chapters[i],line=c.lines[state.line];$('chapterLabel').textContent=String(i+1).padStart(2,'0')+' / '+c.name;$('storyTitle').textContent=line[0];$('storyBody').textContent=line[1];$('place').textContent=c.place;$('next').innerHTML=c.next+' <span>→</span>';document.querySelectorAll('[data-line]').forEach(b=>b.setAttribute('aria-current',String(+b.dataset.line===state.line)));document.querySelectorAll('button[data-chapter]').forEach(b=>b.setAttribute('aria-current',b.dataset.chapter===state.chapter?'step':'false'));}
function setLine(n){state.line=clamp(n,0,3);state.lineTime=0;paintStory();}
function stopAuto(){state.auto=false;document.querySelector('[data-action=walk]')?.setAttribute('aria-pressed','false');}
function buttons(){const items=state.chapter==='train'?[['view','차창에 기대기'],['scenery','다음 풍경']]:state.chapter==='forest'?[['walk','천천히 걷기'],['flowers','꽃'],['birds','새'],['animals','작은 동물']]:[['walk','파도 따라 걷기'],['back','뒤돌아보기']];$('actions').innerHTML=items.map(([id,label])=>`<button data-action="${id}" ${['walk','back'].includes(id)?'aria-pressed="false"':''}>${label}</button>`).join('');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
function enterChapter(id){state.chapter=id;state.sceneTime=0;state.line=0;state.lineTime=0;state.hold=false;state.back=false;stopAuto();keys.clear();viewMove=null;drag=null;document.body.dataset.chapter=id;
 Object.entries(worlds).forEach(([key,w])=>w.root.visible=key===id);const p=palettes[id];renderer.toneMappingExposure=id==='train'?.95:1.05;scene.fog.color.set(p.fog);scene.fog.density=p.density;skyU.top.value.set(p.top);skyU.bottom.value.set(p.bottom);skyU.direction.value.set(id==='beach'?-.65:.6,id==='beach'?.18:.4,.5).normalize();sun.position.set(...p.pos);sun.color.set(p.sun);sun.intensity=p.intensity;ambient.groundColor.set(p.ground);ambient.intensity=id==='forest'?2.4:2.1;
 if(id==='train'){state.x=-.35;state.z=0;state.yaw=-Math.PI/2+.1;state.pitch=-.08;state.route=0;}else if(id==='forest'){state.x=trailX(-33);state.z=-33;state.yaw=-.12;state.pitch=-.015;}else{state.x=1.2;state.z=-17;state.yaw=-.12;state.pitch=-.09;worlds.beach.footsteps.reset();state.auto=!reduced;}
 $('stay').setAttribute('aria-pressed','false');$('stay').textContent='천천히 머무르기';$('gesture').textContent=id==='train'?'드래그로 창밖 둘러보기':innerWidth<700?'드래그로 둘러보기 · 화살표로 걷기':'드래그로 둘러보기 · W A S D로 걷기';buttons();if(state.auto)document.querySelector('[data-action=walk]')?.setAttribute('aria-pressed','true');paintStory();}
function switchChapter(id){if(!state.started)begin(false);stopAuto();keys.clear();viewMove=null;transition={start:performance.now(),id,moved:false};}
async function begin(withSound=true){if(state.started)return;state.started=true;document.body.classList.add('started');$('reader').hidden=false;$('status').textContent='어느 장면에서든 오래 머물러도 괜찮아요.';if(withSound){try{await audio.start();updateSound();$('status').textContent=audio.failed?'바람 소리와 함께 천천히 떠나요.':'음악 없이, 곁에 있는 소리들만.';}catch{$('status').textContent='소리 버튼을 눌러 자연음을 켜보세요.';}}}
function viewTo(target){viewMove={start:performance.now(),from:{x:state.x,z:state.z,yaw:state.yaw,pitch:state.pitch},to:target};}
function action(id){stopAuto();if(id==='view'){viewTo({x:-.35,z:0,yaw:-Math.PI/2,pitch:-.04});setLine(1);}else if(id==='scenery'){state.route=state.route<.36?.44:state.route<.7?.8:.05;setLine(state.route>.7?3:2);}else if(id==='walk'){state.auto=true;document.querySelector('[data-action=walk]')?.setAttribute('aria-pressed','true');state.back=false;state.yaw=state.chapter==='beach'?-.1:state.yaw;state.pitch=-.05;$('status').textContent='천천히 걸어요. 직접 움직이면 산책이 멈춥니다.';}else if(id==='back'){state.back=!state.back;viewTo({x:state.x,z:state.z,yaw:state.back?Math.PI-.08:-.12,pitch:state.back?-.37:-.09});document.querySelector('[data-action=back]').setAttribute('aria-pressed',String(state.back));setLine(2);}else{viewTo(worlds.forest.focus[id]);setLine(id==='animals'?2:1);}}
function resize(){const r=canvas.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio||1,r.width<700?1.35:1.65));renderer.setSize(r.width,r.height,false);}new ResizeObserver(resize).observe(canvas);resize();
function update(ms){requestAnimationFrame(update);if(document.hidden){last=ms;return}if(ms-last<1000/30)return;const dt=Math.min(.04,(ms-last)/1000);last=ms;state.time+=dt;const advance=state.started&&!state.hold?dt:0;state.sceneTime+=state.started?dt:0;
 if(transition){const p=Math.min(1,(ms-transition.start)/(reduced?1:1500));$('sceneFade').style.opacity=String(Math.sin(p*Math.PI));if(p>=.5&&!transition.moved){enterChapter(transition.id);transition.moved=true;}if(p===1){transition=null;$('sceneFade').style.opacity='0';}}
 else if(viewMove){const p=Math.min(1,(ms-viewMove.start)/(reduced?1:1600)),f=p*p*(3-2*p),a=viewMove.from,b=viewMove.to;for(const key of ['x','z','yaw','pitch'])state[key]=T.MathUtils.lerp(a[key],b[key],f);if(p===1)viewMove=null;}
 else if(state.started&&state.chapter!=='train'){const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),r=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0);let dx=0,dz=0;if(f||r){stopAuto();const n=Math.hypot(f,r);dx=(-Math.sin(state.yaw)*f+-Math.cos(state.yaw)*r)/n*dt*1.4;dz=(Math.cos(state.yaw)*f+-Math.sin(state.yaw)*r)/n*dt*1.4;}
  else if(state.auto&&!state.hold){if(state.chapter==='forest'){const tz=Math.min(-15,state.z+2),tx=trailX(tz);state.yaw=T.MathUtils.lerp(state.yaw,-Math.atan2(tx-state.x,tz-state.z),dt*2);dx=-Math.sin(state.yaw)*dt*1.05;dz=Math.cos(state.yaw)*dt*1.05;if(state.z>=-15.1)stopAuto();}else{dx=(1.2-state.x)*dt*.4;dz=dt*1.1;if(state.sceneTime>4&&state.sceneTime<4.1){stopAuto();$('status').textContent='발끝에 닿는 파도와, 지나온 걸음들.';}if(state.z>29)stopAuto();}}
  if(dx||dz){if(state.chapter==='forest'){const p=stepWalker(state,dx,dz,worlds.forest.colliders);state.x=p.x;state.z=clamp(p.z,-36,-13);}else{state.z=clamp(state.z+dz,-30,34);state.x=clamp(state.x+dx,shoreX(state.z)+1.8,9);worlds.beach.footsteps.move(state.x,state.z,state.time);}}
 }
 if(advance&&!transition){state.lineTime+=advance;if(state.lineTime>19&&state.line<3)setLine(state.line+1);if(state.chapter==='train')state.route=Math.min(1,state.route+advance/62);}
 const active=worlds[state.chapter];if(state.chapter==='train'){active.update(reduced?0:state.sceneTime,state.route);const routeColor=state.route>.7?'#c9d6d0':'#cbd5bf';scene.fog.color.lerp(new T.Color(routeColor),dt*.4);}else if(state.chapter==='forest')active.update(reduced?0:state.time);else active.update(reduced?0:state.time,reduced?0:dt);
 const y=state.chapter==='train'?1.5:state.chapter==='forest'?walkHeight(state.x,state.z)+1.65:sandHeight(state.x,state.z)+1.65;camera.position.set(state.x,y,state.z);camera.rotation.order='YXZ';camera.rotation.set(state.pitch,Math.PI-state.yaw,0);sky.position.copy(camera.position);audio.update(state.chapter,state.time,state.route);
 uiClock+=dt;if(uiClock>.25){uiClock=0;updateSound();canvas.dataset.chapter=state.chapter;canvas.dataset.position=[state.x,state.z].map(v=>v.toFixed(2)).join(',');canvas.dataset.footprints=String(worlds.beach.footsteps.total);canvas.dataset.line=String(state.line);canvas.dataset.route=state.route.toFixed(2);canvas.dataset.frames=String(renderer.info.render.frame);canvas.dataset.drawCalls=String(renderer.info.render.calls);canvas.dataset.audioReady=String(audio.ready);}renderer.render(scene,camera);
}
enterChapter('train');requestAnimationFrame(update);$('status').textContent='여행이 준비됐어요. 잠깐 쉬어가세요.';
$('start').onclick=()=>begin(true);document.querySelectorAll('button[data-chapter]').forEach(b=>b.onclick=()=>switchChapter(b.dataset.chapter));document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>setLine(+b.dataset.line));$('next').onclick=()=>{const i=chapters.findIndex(c=>c.id===state.chapter);switchChapter(chapters[(i+1)%3].id);};
$('stay').onclick=()=>{state.hold=!state.hold;if(state.hold)stopAuto();$('stay').setAttribute('aria-pressed',String(state.hold));$('stay').textContent=state.hold?'다시 천천히 흐르기':'천천히 머무르기';$('status').textContent=state.hold?'이곳에 조금 더 머물러요. 자연의 소리는 계속됩니다.':'이야기가 다시 천천히 흐릅니다.';};
$('sound').onclick=async()=>{try{await audio.toggle();updateSound();}catch{$('status').textContent='브라우저에서 소리를 재생할 수 없어요.';}};$('volume').oninput=e=>{audio.setVolume(+e.target.value/100);$('volumeValue').textContent=e.target.value+'%';};$('credits').onclick=()=>{keys.clear();$('creditsDialog').showModal();};$('closeCredits').onclick=()=>$('creditsDialog').close();
$('clean').onclick=()=>{state.clean=true;document.body.classList.add('clean');$('restore').hidden=false;};$('restore').onclick=()=>{state.clean=false;document.body.classList.remove('clean');$('restore').hidden=true;};
function cancelView(){viewMove=null;stopAuto();}canvas.addEventListener('pointerdown',e=>{if(e.button!==0||transition)return;cancelView();drag={x:e.clientX,y:e.clientY,yaw:state.yaw,pitch:state.pitch};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;state.yaw=drag.yaw-(e.clientX-drag.x)*.003;state.pitch=clamp(drag.pitch-(e.clientY-drag.y)*.0025,-.65,.5);if(state.chapter==='train')state.yaw=clamp(state.yaw,-Math.PI+.35,-.35);});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);
const codes=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];document.addEventListener('keydown',e=>{if($('creditsDialog').open||state.chapter==='train')return;if(codes.includes(e.code)){e.preventDefault();begin(false);cancelView();keys.add(e.code);}});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();drag=null;});const moveCodes={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'};document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();begin(false);cancelView();keys.add(moveCodes[b.dataset.move]);b.setPointerCapture(e.pointerId);};for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(moveCodes[b.dataset.move]));});
